def documents():
    raw = json.loads(zlib.decompress(base64.b85decode(FIXTURE)))
    return {role: receiver.document(body.encode()) for role, body in raw.items()}


def refresh(docs):
    """Rebind authored metadata so each semantic control reaches its own fence."""
    def pin(role):
        raw = receiver.canonical(docs[role])
        return {"path": "/authored/" + role + ".json", "sha256": sha256(raw).hexdigest(), "size_bytes": len(raw)}
    docs["execution_freeze"]["source_evolution_sha256"] = pin("source_evolution")["sha256"]
    for role in ("native_command", "native_command_result"):
        docs[role]["freeze_sha256"] = pin("execution_freeze")["sha256"]
    for role in ("phase_requests", "phase_launches", "phase_lifecycles", "phase_budgets", "phase_environments"):
        leaf = receiver.ARTIFACT_KEYS[role].split("/")[-1]
        docs["native_result"]["audit_sha256"][leaf] = pin(role)["sha256"]
    for role in receiver.ROLES[1:]:
        docs["qualification"]["artifact_sha256"][receiver.ARTIFACT_KEYS[role]] = pin(role)["sha256"]
    return {role: pin(role) for role in receiver.ROLES}


def replace(docs, path, value):
    obj = docs
    for component in path[:-1]:
        obj = obj[component]
    obj[path[-1]] = value


class MetadataControls(unittest.TestCase):
    def test_authored_baseline_preserves_cooperative_ceiling(self):
        docs = documents()
        result = receiver.derive(docs, refresh(docs))
        self.assertEqual(len(result["deadline_cases"]), 2)
        self.assertEqual(len(result["phase_population"]), 6)
        self.assertEqual(result["resources"]["recorded_next_sequence"], 7)
        self.assertFalse(result["test_observations"]["counts_summed"])
        self.assertFalse(result["test_observations"]["native_interruption_execution_attested"])
        self.assertEqual(result["production_tasks_closed"], [])
        self.assertFalse(result["resources"]["live_cleanup_reobserved"])

    def test_no_named_source_or_tool_bodies_are_selected(self):
        docs = documents()
        result = receiver.derive(docs, refresh(docs))
        self.assertEqual(result["source_preservation"]["all_named_source_tool_test_and_prior_bodies_opened"], 0)
        self.assertEqual(set(result["unfollowed_body_closure"].values()), {"unknown_not_selected"})
        for flag in receiver.FALSE_FLAGS:
            self.assertIs(receiver.scope()[flag], False)
        for field in receiver.ZERO_FIELDS:
            self.assertIs(type(receiver.scope()[field]), int)
            self.assertEqual(receiver.scope()[field], 0)


